// Renders the generated, git-ignored config the setup deploys with
// (apps/api/wrangler.<env>.generated.jsonc) from the committed apps/api/wrangler.jsonc and the
// instance's settings (instance.ts), and reads an environment back for the checks.
//
// Why a generated file instead of writing into wrangler.jsonc: the name, address and ids belong
// to one instance and one Cloudflare account, the repository is public and forked, and
// `git pull` to update an instance must not conflict with local edits. The committed file has
// one generic template environment (env.production) with placeholders.

import { applyEdits, modify, parse, type ParseError, printParseErrorCode } from 'jsonc-parser';
import type { BuildInfo } from './build-info.ts';
import { originOf } from './domain.ts';
import type { Instance } from './instance.ts';

export const PLACEHOLDER_ID = '00000000-0000-0000-0000-000000000000';

export interface EnvFacts {
  env: string;
  workerName: string;
  d1: { binding: string; databaseName: string; databaseId: string; index: number } | null;
  r2: { binding: string; bucketName: string } | null;
  customDomains: string[];
  workersDev: boolean;
  vars: Record<string, string>;
  hasAssets: boolean;
  accountId: string | null;
}

export class ConfigError extends Error {}

interface RawBinding {
  binding?: unknown;
  database_name?: unknown;
  database_id?: unknown;
  bucket_name?: unknown;
}

interface RawEnv {
  name?: unknown;
  account_id?: unknown;
  d1_databases?: RawBinding[];
  r2_buckets?: RawBinding[];
  routes?: { pattern?: unknown; custom_domain?: unknown }[];
  workers_dev?: unknown;
  vars?: Record<string, unknown>;
  assets?: unknown;
  observability?: { enabled?: unknown; head_sampling_rate?: unknown } & Record<string, unknown>;
}

interface RawConfig extends RawEnv {
  env?: Record<string, RawEnv>;
}

function parseConfig(text: string): RawConfig {
  const errors: ParseError[] = [];
  const config = parse(text, errors, { allowTrailingComma: true }) as unknown;
  const first = errors[0];
  if (first) {
    throw new ConfigError(`invalid wrangler.jsonc: ${printParseErrorCode(first.error)}`);
  }
  if (typeof config !== 'object' || config === null)
    throw new ConfigError('invalid wrangler.jsonc');
  return config as RawConfig;
}

const str = (v: unknown): string | undefined => (typeof v === 'string' ? v : undefined);

export function readEnvFacts(
  text: string,
  env: string,
  d1Binding = 'DB',
  r2Binding = 'THUMBNAILS',
): EnvFacts {
  const config = parseConfig(text);
  const raw = config.env?.[env];
  if (!raw) {
    const known = Object.keys(config.env ?? {}).join(', ') || 'none';
    throw new ConfigError(`wrangler.jsonc has no env.${env} (environments: ${known})`);
  }
  // `name` is inherited with an "-<env>" suffix when the environment doesn't set one.
  const workerName = str(raw.name) ?? `${str(config.name) ?? 'worker'}-${env}`;

  // Bindings are not inherited from the top level, so only the environment's own count.
  const d1Index = (raw.d1_databases ?? []).findIndex((d) => d.binding === d1Binding);
  const d1Raw = raw.d1_databases?.[d1Index];
  const d1 = d1Raw
    ? {
        binding: d1Binding,
        databaseName: str(d1Raw.database_name) ?? '',
        databaseId: str(d1Raw.database_id) ?? '',
        index: d1Index,
      }
    : null;
  if (d1 && !d1.databaseName)
    throw new ConfigError(`env.${env}: ${d1Binding} has no database_name`);

  const r2Raw = (raw.r2_buckets ?? []).find((b) => b.binding === r2Binding);
  const r2 = r2Raw ? { binding: r2Binding, bucketName: str(r2Raw.bucket_name) ?? '' } : null;
  if (r2 && !r2.bucketName) throw new ConfigError(`env.${env}: ${r2Binding} has no bucket_name`);

  const customDomains = (raw.routes ?? [])
    .filter((r) => r.custom_domain === true)
    .map((r) => str(r.pattern))
    .filter((p): p is string => p !== undefined);

  const vars = Object.fromEntries(
    Object.entries(raw.vars ?? {}).map(([k, v]) => [
      k,
      typeof v === 'string' ? v : JSON.stringify(v),
    ]),
  );

  return {
    env,
    workerName,
    d1,
    r2,
    customDomains,
    // workers_dev is inherited; it defaults to true when there are no routes.
    workersDev:
      typeof raw.workers_dev === 'boolean'
        ? raw.workers_dev
        : typeof config.workers_dev === 'boolean'
          ? config.workers_dev
          : customDomains.length === 0,
    vars,
    hasAssets: raw.assets !== undefined || config.assets !== undefined,
    accountId: str(raw.account_id) ?? str(config.account_id) ?? null,
  };
}

export const GENERATED_HEADER =
  '// GENERATED by `pnpm run setup` from wrangler.jsonc and .instance.<env>.json. Git-ignored: it\n' +
  "// holds this instance's address and this account's resource ids. Do not edit: edit\n" +
  '// wrangler.jsonc (shared) or run the setup again with other flags (this instance).\n';

/** The environment the committed config uses as the template for every instance. */
export const TEMPLATE_ENV = 'production';

/**
 * Wrangler's error when the account has not opted in to Workers Analytics Engine (code 10089).
 * The opt-in takes effect only after creating a dataset on the dashboard page (any name).
 */
export function analyticsEngineNotEnabled(output: string): boolean {
  return /\b10089\b|enable analytics engine/i.test(output);
}

export const analyticsEngineUrl = (accountId: string) =>
  `https://dash.cloudflare.com/${accountId}/workers/analytics-engine`;

export interface RenderOptions {
  /** false drops the Analytics Engine binding (`--no-metrics`, or the account has no AE). */
  metrics?: boolean;
  /** Becomes the APP_COMMIT and APP_BUILT_AT vars; without it the Worker reports "dev". */
  build?: BuildInfo | null;
}

/**
 * The committed config with env.<env> built from the template environment and the instance: the
 * Worker name, the route, APP_ORIGIN, EMAIL_FROM, the resource names and, when known, the
 * account and D1 ids (placeholders otherwise, for a dry run). Everything else in the template,
 * such as bindings added later, is kept as is. Other environments are dropped.
 */
export function renderInstanceConfig(
  text: string,
  env: string,
  inst: Instance,
  ids: { accountId: string | null; databaseId: string | null },
  opts: RenderOptions = {},
): string {
  const d1Binding = 'DB';
  const r2Binding = 'THUMBNAILS';
  const config = parseConfig(text);
  const template = config.env?.[env] ?? config.env?.[TEMPLATE_ENV];
  if (!template) throw new ConfigError(`wrangler.jsonc has no env.${TEMPLATE_ENV} template`);
  const block = structuredClone(template) as RawEnv & Record<string, unknown>;

  block.name = inst.workerName;
  if (ids.accountId) block.account_id = ids.accountId;
  else delete block.account_id;
  if (inst.route.kind === 'custom_domain') {
    block.routes = [{ pattern: inst.route.domain, custom_domain: true }];
    block.workers_dev = false;
  } else {
    delete block.routes;
    block.workers_dev = true;
  }
  const vars: Record<string, unknown> = { ...(block.vars ?? {}) };
  vars['APP_ORIGIN'] = originOf(inst.route, inst.workerName);
  if (inst.emailFrom) vars['EMAIL_FROM'] = inst.emailFrom;
  else delete vars['EMAIL_FROM'];
  if (opts.build) {
    vars['APP_COMMIT'] = opts.build.commit;
    vars['APP_BUILT_AT'] = opts.build.builtAt;
  }
  block.vars = vars;

  const d1 = (block.d1_databases ?? []).find((d) => d.binding === d1Binding);
  if (d1) {
    d1.database_name = inst.d1.databaseName;
    d1.database_id = ids.databaseId ?? PLACEHOLDER_ID;
  }
  const r2 = (block.r2_buckets ?? []).find((b) => b.binding === r2Binding);
  if (r2) r2.bucket_name = inst.r2.bucketName;
  // The Worker treats a missing METRICS binding as metrics off (src/metrics/points.ts).
  if (opts.metrics === false) delete block['analytics_engine_datasets'];
  // Workers Logs: the instance's sampling rate, else the template's. The Worker
  // reads it back from LOG_SAMPLING_RATE to estimate its log events in the limits panel.
  const observability = { ...(block.observability ?? config.observability ?? {}) };
  if (inst.logSampling !== undefined) observability.head_sampling_rate = inst.logSampling;
  block.observability = observability;
  const rate = observability.head_sampling_rate;
  if (typeof rate === 'number') vars['LOG_SAMPLING_RATE'] = String(rate);

  const fmt = { formattingOptions: { insertSpaces: true, tabSize: 2 } };
  const out = applyEdits(text, modify(text, ['env'], { [env]: block }, fmt));
  return GENERATED_HEADER + out;
}
